#!/usr/bin/env bash
set -uo pipefail
REPO_DIR="${CARE_ASD_REPO_DIR:-$HOME/Dung_TDTU/CARE_ASD}"; DATA_ROOT="${CARE_ASD_DATA_ROOT:-$HOME/Dung_TDTU/data/CARE_ASD}"; cd "$REPO_DIR"; RUN_FILE="outputs/fp_naa/latest_run_id.txt"
if [ ! -f "$RUN_FILE" ]; then printf 'No FP-NAA C0 run has been started.\n'; exit 0; fi
RUN_ID="$(cat "$RUN_FILE")"; JOB_DIR="outputs/fp_naa/$RUN_ID"; CACHE_DIR="$DATA_ROOT/fp_naa/beats_cache/dev/beats_iter3_stereo_10s_v1"; REPORT_DIR="reports/fp_naa/$RUN_ID/c0_baseline"; printf 'RUN_ID=%s\n\nSTATE:\n' "$RUN_ID"; [ -f "$JOB_DIR/state.env" ] && cat "$JOB_DIR/state.env" || printf 'state file not created yet\n'; printf '\nPROCESS:\n'; pgrep -af '[r]un_fp_naa_baseline.sh|care-asd fp-naa|curl.*BEATs_iter3' || printf 'no matching process\n'; printf '\nCACHE PROGRESS:\n'; [ -f "$CACHE_DIR/progress.env" ] && cat "$CACHE_DIR/progress.env" || printf 'cache progress not created yet\n'; printf '\nBASELINE PROGRESS:\n'; [ -f "$REPORT_DIR/progress.env" ] && cat "$REPORT_DIR/progress.env" || printf 'baseline progress not created yet\n'; printf '\nGPU:\n'; nvidia-smi --query-compute-apps=pid,process_name,used_memory --format=csv,noheader 2>/dev/null || true; printf '\nLOG TAIL:\n'; tail -n 30 "$JOB_DIR/fp_naa_baseline.log" 2>/dev/null || true; if [ -f "$REPORT_DIR/summary.csv" ]; then printf '\nSUMMARY:\n'; column -s, -t < "$REPORT_DIR/summary.csv"; fi; if [ -f "$REPORT_DIR/gate.json" ]; then printf '\nGATE:\n'; cat "$REPORT_DIR/gate.json"; fi
